import{z as i,x as s,o as l,c as d,q as A,j as n,D as e,d as B,s as r,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"自动赎回谱系：雪球深化","description":"","frontmatter":{"title":"自动赎回谱系：雪球深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ot-autocall-snowball-deep.md","filePath":"quant/ot-autocall-snowball-deep.md","lastUpdated":1791063341000}'),p={name:"quant/ot-autocall-snowball-deep.md"};function u(F,a,D,c,h,m){const t=s("Mermaid");return l(),d("div",null,[a[2]||(a[2]=A('<h1 id="自动赎回谱系-雪球深化" tabindex="-1">自动赎回谱系：雪球深化 <a class="header-anchor" href="#自动赎回谱系-雪球深化" aria-label="Permalink to &quot;自动赎回谱系：雪球深化&quot;">​</a></h1><div class="epigraph"><p>雪球不是一只产品，是一张字段表：期限、敲出线、降敲节奏、观察时钟、记忆票息——每改一格，价格与对冲就换一个家族。</p><footer>—— 据 Broadie, Glasserman and Kou, Mathematical Finance, 1997；条款口径据交易所与协会公开规则整理</footer></div><p><a href="/quant/rc2-map">上一课</a>把研究协作收进两种可重放：引擎重放计算，台账重放决策——显式、可数、挂判据，让一次实验可复述、一群人的研究可评审。本课是「结构化产品与场外」的第一课：场外的条款、估值与限额同样是「每次变更可追溯」的对象，那三条机制在这里照常生效。主干已交付三块基石：<a href="/quant/autocallable">autocallable</a> 的状态机、<a href="/quant/snowball-pricing">雪球定价</a> 在合约观察网格上的票息反解、<a href="/quant/snowball-knockin-cascade">敲入级联</a> 的信用路径。本课程不重推公式，而是把雪球当成一个谱系来管理：发行台面上同时挂着几十种变体，谱系不清，估值与限额就没有比较基准。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干课回答的是「一只雪球值多少」，实务回答的是「这一批变体各自值多少、风险差在哪」。把变体当新产品从零定价，账本失去可比性；把变体当同一产品只改参数，又会在字段改变观察时钟或行权结构的场合漏掉质变——敲出观察从每月改每季只是数值变化，敲入时钟从收盘改盘中就是另一族触碰分布。缺口因此是先钉一张分类轴：把字段分成连续可微的数值字段与改变结构的状态字段，前者进报价，后者换族处理。</p><p><span class="marginnote">直觉类比：雪球是「你把震荡行情的保险卖给发行商」——行情温和，你按月收高票息，像滚雪球；行情大跌，你从收租人瞬间变成接盘人，下跌损失自己扛。高票息不是白给的，是你卖出的暴跌保险的保费。</span></p><h3 id="三条分类轴" tabindex="-1">三条分类轴 <a class="header-anchor" href="#三条分类轴" aria-label="Permalink to &quot;三条分类轴&quot;">​</a></h3><p>谱系按支付与时钟切成三轴。敲出侧：敲出水平、降敲节奏、观察频率、早赎权；敲入侧：敲入线、观察时钟、保护垫；支付侧：票息类型（固定、或有、记忆、按月 phoenix）与敲入后参与方式（全额承担、部分参与、带执行价的看跌）。</p><p><span class="marginnote">敲出按月观察、敲入接近每日观察——两种时钟并存正是高票息的来源：投资者卖出的是每日判定的尾部。Broadie–Glasserman–Kou 平移量随 \\(\\sqrt{\\Delta t}\\) 缩放，间隔不同，同一根敲入线对应的连续等价障碍就不同，见<a href="/quant/barrier-monitoring">监控频率</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每条轴给出定价与对冲后果，变体是轴上的坐标而不是独立产品。敲出观察从每月改每季，触碰概率上升，票息反解数值上升；降敲使敲出线随时间下行，Vega 变号的位置跟着敲出线穿过现价的窗口移动——<a href="/quant/vt-exotic-risk-map">上一课</a>的障碍前变号在此按时间展开。敲入时钟从收盘改盘中，敲入概率与数字缺口一起变大，对冲带相应上移。记忆票息把状态从「是否敲入」扩成「欠几期」，估值网格多一维历史计数；phoenix 把票息切成按月或有，delta 的时间结构随之切细。最差表现把相关抬成一等项，篮子维度进<a href="/quant/dispersion-corr-prem">相关溢价</a>的口径。</p><p><span class="marginnote">数字实例：敲出线 100%、敲入线 80%、月票息 1.5%。若第 4 个观察日标的到期初期 102%，合约提前终止，拿 4 期共 6% 票息走人；若某天盘中跌破 80%，之后涨回来也改变不了身份——到期仍按实际跌幅承担亏损，跌 25% 就亏 25%。</span></p>',12)),(l(),n(o,null,{default:e(()=>[r(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%AD%97%E6%AE%B5%E8%A1%A8%EF%BC%9A%E6%9C%9F%E9%99%90%2F%E6%95%B2%E5%87%BA%E7%BA%BF%2F%E9%99%8D%E6%95%B2%2F%E6%97%B6%E9%92%9F%2F%E7%A5%A8%E6%81%AF%22%5D%20--%3E%20AX1%5B%22%E6%95%B2%E5%87%BA%E8%BD%B4%EF%BC%9A%E6%B0%B4%E5%B9%B3%E3%80%81%E9%99%8D%E6%95%B2%E3%80%81%E9%A2%91%E7%8E%87%22%5D%0A%20%20F%20--%3E%20AX2%5B%22%E6%95%B2%E5%85%A5%E8%BD%B4%EF%BC%9A%E6%95%B2%E5%85%A5%E7%BA%BF%E3%80%81%E6%97%B6%E9%92%9F%E3%80%81%E4%BF%9D%E6%8A%A4%E5%9E%AB%22%5D%0A%20%20F%20--%3E%20AX3%5B%22%E6%94%AF%E4%BB%98%E8%BD%B4%EF%BC%9A%E7%A5%A8%E6%81%AF%E7%B1%BB%E5%9E%8B%E3%80%81%E5%8F%82%E4%B8%8E%E6%96%B9%E5%BC%8F%22%5D%0A%20%20AX1%20--%3E%20GRID%5B%22%E5%90%8C%E4%B8%80%E5%90%88%E7%BA%A6%E7%BD%91%E6%A0%BC%E4%B8%8A%E7%9A%84%E5%9D%90%E6%A0%87%22%5D%0A%20%20AX2%20--%3E%20GRID%0A%20%20AX3%20--%3E%20GRID%0A%20%20GRID%20--%3E%20RISK%5B%22%E5%B8%8C%E8%85%8A%E7%BB%93%E6%9E%84%EF%BC%9A%E5%8F%98%E5%8F%B7%E4%BD%8D%E7%BD%AE%E3%80%81%E5%87%B8%E6%80%A7%E3%80%81%E7%8A%B6%E6%80%81%E7%BB%B4%E5%BA%A6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"票息必须逐字段反解，因为票息是使合约公允的或有期权费：记 \\(c\\,A+B=1\\)，其中 \\(A\\) 是未敲出时各期票息贴现因子沿存活路径的期望，\\(B\\) 是敲入后支付沿全部路径的贴现期望；任何字段改变都改写 \\(A\\)、\\(B\\) 里的路径集合，而不是线性修正。线性近似只在三处失效：敲入线附近、降敲线穿过现价的窗口、期限压缩的短端——字段微动，票息跳档。希腊随轴分族：敲出轴决定 Vega 变号的时空位置；敲入轴决定 delta 凸性与 gap 的量级；支付轴决定状态维度。不这么记账会错在哪：把降敲雪球当平敲报价，敲出线穿价的那个月 delta 突然对不上；把记忆票息当固定票息，敲入后每期负债都被低估。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"常见误区：把「记忆票息」当成「跌了也照付」。记忆只是记住「上次敲出时欠你几期」；一旦敲入，欠息连同本金一起暴露在条款里——「欠着」不等于「必付」，支付轴那一格决定它最终是资产还是空头欠条。")],-1)),(l(),n(o,null,{default:e(()=>[r(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E9%9B%AA%E7%90%83%E5%AD%98%E7%BB%AD%E4%B8%AD%22%5D%20--%3E%20Q1%7B%22%E7%9B%98%E4%B8%AD%E8%A7%A6%E5%8F%8A%E6%95%B2%E5%85%A5%E7%BA%BF%3F%22%7D%0A%20%20Q1%20--%3E%7C%22%E6%98%AF%22%7C%20KI%5B%22%E6%A0%87%E8%AE%B0%E5%B7%B2%E6%95%B2%E5%85%A5%20%E6%89%BF%E6%8B%85%E4%B8%8B%E8%A1%8C%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%90%A6%22%7C%20C%5B%22%E7%BB%A7%E7%BB%AD%E8%AE%A1%E7%A5%A8%E6%81%AF%22%5D%0A%20%20S%20--%3E%20Q2%7B%22%E8%A7%82%E5%AF%9F%E6%97%A5%E9%AB%98%E4%BA%8E%E6%95%B2%E5%87%BA%E7%BA%BF%3F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20OUT%5B%22%E6%8F%90%E5%89%8D%E8%B5%8E%E5%9B%9E%20%E6%9C%AC%E6%81%AF%E7%A6%BB%E5%9C%BA%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20C%0A%20%20KI%20--%3E%20Q3%7B%22%E5%88%B0%E6%9C%9F%E5%89%8D%E6%98%AF%E5%90%A6%E6%95%B2%E5%87%BA%3F%22%7D%0A%20%20C%20--%3E%20Q3%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20OUT%0A%20%20Q3%20--%3E%7C%22%E5%90%A6%22%7C%20LOSS%5B%22%E5%88%B0%E6%9C%9F%E6%8C%89%E6%A0%87%E7%9A%84%E4%BA%8F%E6%8D%9F%E7%BB%93%E7%AE%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给变体逐一定价，也不比较「哪个变体更划算」——那是适当性约束下的销售问题，口径沿<a href="/quant/snowball-pricing">雪球定价</a>：不得按保本陈述，销售受适当性管理。谱系表是估值与对冲的字典，不是风险的全部：信用、保证金与文档是后课缺口。下一课把没有敲出提前终止、更像「固收增强」的 FCN 单独拆开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>雪球谱系按敲出、敲入、支付三轴管理，变体是坐标不是独立产品。</li><li>字段分两类：连续可微的数值字段与改变结构的状态字段，后者换族处理。</li><li>票息逐字段反解；敲入线附近、降敲穿价窗口、短端三处线性近似失效。</li><li>希腊结构随轴分族：变号位置、凸性量级、状态维度。</li><li>出处：Broadie, Glasserman and Kou, <em>Mathematical Finance</em>, 1997；结构口径沿 <a href="/quant/autocallable">autocallable</a> 与<a href="/quant/snowball-pricing">雪球定价</a>两课。</li></ul>',4))])}const b=i(p,[["render",u]]);export{f as __pageData,b as default};
